import { Image } from "expo-image";
import { useEffect, useState } from "react";
import { View } from "react-native";

import { ThemedText } from "@/components/themed-text";
import { useTheme } from "@/hooks/use-theme";

function getInitials(name: string) {
	const parts = name.split(/\s+/).filter(Boolean);
	const letters = parts.map((p) => p[0]?.toUpperCase()).filter(Boolean);
	return letters.slice(0, 2).join("") || "?";
}

export function Avatar({
	name,
	image,
	headers,
	size = 32,
}: {
	name: string;
	image?: string | null;
	headers?: Record<string, string>;
	size?: number;
}) {
	const theme = useTheme();
	const initials = getInitials(name);
	const [imageFailed, setImageFailed] = useState(false);

	useEffect(() => {
		setImageFailed(false);
	}, [image]);

	if (image && !imageFailed) {
		return (
			<Image
				source={{ uri: image, headers }}
				style={{ width: size, height: size, borderRadius: size / 2 }}
				contentFit="cover"
				onError={() => setImageFailed(true)}
			/>
		);
	}

	return (
		<View
			style={{
				width: size,
				height: size,
				borderRadius: size / 2,
				backgroundColor: theme.primary,
				alignItems: "center",
				justifyContent: "center",
			}}
		>
			<ThemedText
				type="smallBold"
				themeColor="primaryForeground"
				style={{ fontSize: size * 0.4, lineHeight: size * 0.4 * 1.4 }}
			>
				{initials}
			</ThemedText>
		</View>
	);
}

import { useNavigation } from "expo-router";
import { useEffect, useState } from "react";
import { Pressable } from "react-native";

import { Avatar } from "@/components/avatar";
import { AUTH_BASE_URL, authClient } from "@/lib/auth-client";

export function AppHeaderLeft() {
	const navigation = useNavigation<{ openDrawer: () => void }>();
	const { data } = authClient.useSession();
	const user = data?.user;
	const [cookie, setCookie] = useState<string>();

	useEffect(() => {
		let active = true;
		authClient.getCookie().then((value) => {
			if (active) setCookie(value);
		});
		return () => {
			active = false;
		};
	}, []);

	const imageUri = user?.image?.startsWith("http")
		? user.image
		: user?.image
			? `${AUTH_BASE_URL}/api/user-assets/${encodeURIComponent(user.image)}`
			: undefined;

	return (
		<Pressable
			onPress={() => navigation.openDrawer()}
			hitSlop={8}
			accessibilityRole="button"
			accessibilityLabel="Open league menu"
		>
			<Avatar
				name={user?.name ?? ""}
				image={imageUri}
				headers={cookie ? { cookie } : undefined}
				size={32}
			/>
		</Pressable>
	);
}
